            .items
            .contains_key(key)
            .then(|| self.context.ids.item("cell", key))
    }

    /// Returns the latest user-requested selected keys.
    #[must_use]
    pub const fn requested_selected_keys(&self) -> Option<&BTreeSet<Key>> {
