fn render_announcement_content(
    message: &str,
    last_message: Option<&str>,
    voiceover_toggle: &mut bool,
) -> String {
    let is_repeat = last_message == Some(message);

    if is_repeat {
        *voiceover_toggle = !*voiceover_toggle;
        if *voiceover_toggle {
            format!("{message}\u{200D}")
        } else {
            String::from(message)
        }
    } else {
        *voiceover_toggle = false;
        String::from(message)
    }
}

