    pub copied_announcement: MessageFn<dyn Fn(&Locale) -> String + Send + Sync>,

    /// Announcement when copy fails.
    pub error_announcement: MessageFn<dyn Fn(&Locale) -> String + Send + Sync>,
}

impl Default for Messages {
    fn default() -> Self {
        Self {
