    match orientation {
        Orientation::Horizontal => "horizontal",
        Orientation::Vertical => "vertical",
    }
}

const fn direction_value(dir: Direction) -> &'static str {
    match dir {
        Direction::Ltr => "ltr",
        Direction::Rtl => "rtl",
        Direction::Auto => "auto",
    }
}

const fn navigation_keys(orientation: Orientation, dir: Direction) -> (KeyboardKey, KeyboardKey) {
