    pub(crate) fn from_parts(
        nodes: Vec<Node<T>>,
        key_to_index: IndexMap<Key, usize, DefaultHashBuilder>,
    ) -> Self {
        let first_focusable = nodes.iter().position(Node::is_focusable);

        let last_focusable = nodes.iter().rposition(Node::is_focusable);

        Self {
            nodes,
